    for i in range(30000): f.write("2024-01-%02d AB-%03d +5 delivery number %d\n"%(i%28+1,i%300,i))
with open("orders.txt","w") as f:
    for i in range(20000): f.write("SO-%d 2024-02-%02d cust%d AB-%03d*3,CD-001*60\n"%(i,i%28+1,i,i%300))
