echo "== non-utf8 note arg"; mk; s0=$(sha1sum movements.txt); $T/run receive 2024-03-10 AB-100 1 $'\xff'; [ "$s0" = "$(sha1sum movements.txt)" ] && echo UNCHANGED || { echo CHANGED; cat -A movements.txt; }
echo "== non-utf8 note arg, missing movements"; mk; rm movements.txt; $T/run receive 2024-03-10 AB-100 1 $'\xff' | sed -n 1,3p; ls -la movements.txt
echo "== non-utf8 SKU arg history"; mk; $T/run history $'\xff'; $T/run quote $'SO-\xff'; $T/run --dir $'\xff' stock
echo "== LC_ALL=C non-ascii"; mk; LC_ALL=C $T/run history 'é'; LC_ALL=C $T/run receive 2024-03-10 AB-100 1 'café' ; LC_ALL=C PYTHONIOENCODING=ascii $T/run stock | head -4

